"""Find all the instances of naked twins in a unit
    Args:
        unit: a unit defining a set of boxes in the model
        values(dict): a dictionary of the form {'box_name': '123456789', ...}

    Returns:
        an array of tuples with all the naked twin instances in the unit in format [((box1,box2),value),...]
    """
def instancesNaked(unit: Any, values: Any) -> object {
    twoDigits = [
        (box, values[box])
        for box in unit
        if (len(values[box]) == 2)
    ];
    toRemove = [];
    for i in range(0, (len(twoDigits) - 1)) {
        for j in range((i + 1), len(twoDigits)) {
            if (twoDigits[i][1] == twoDigits[j][1]) {
                toRemove += [((twoDigits[i][0], twoDigits[j][0]), twoDigits[i][1])];
            }
        }
    }
    return toRemove;
}

"""Craft an archive download URL from a given version and archive name.

    Despite the name, the `version` is really what the GitHub API for releases calls the `tag_name`.
    Reference: https://docs.github.com/en/rest/releases/releases#get-a-release-by-tag-name
    """
def get_archive_url(version: Any, archive_name: Any) -> object {
    github_base_uri = "https://github.com/phylum-dev/cli/releases";
    archive_url = f"{github_base_uri}/download/{version}/{archive_name}";
    return archive_url;
}

